:- module(web_server_generator, [
    generate_web_server/2,
    generate_web_server/3
]).

/** <module> web_server_generator — Stage 5: Web Server Skeleton Generator
 *
 * Ties together the full conversion pipeline (Stages 2–4) and emits a
 * complete, standalone SWI-Prolog HTTP server program from a terminal
 * Prolog source file.
 *
 * Generated program structure
 * ---------------------------
 *   %% Generated by vetusiapl2webpl — web_server_generator
 *
 *   :- use_module(library(http/thread_httpd)).
 *   :- use_module(library(http/http_dispatch)).
 *   :- use_module(library(http/html_write)).
 *   :- use_module(library(http/http_parameters)).
 *   :- use_module(library(http/http_header)).
 *
 *   :- http_handler(root(.), landing_pad_main, []).
 *   :- http_handler(root(resume_main_1), resume_main_1, [method(post)]).
 *   ...
 *
 *   vetusia_server(Port) :-
 *       http_server(http_dispatch, [port(Port)]).
 *
 *   :- initialization(main, main).
 *   main :- vetusia_server(<Port>).
 *
 *   landing_pad_main(_Request) :- ...    % root GET handler (landing page)
 *   resume_main_1(Request)     :- ...    % POST handler for continuation step 1
 *   ...
 *
 *   <auxiliary clauses from the input program>
 *
 * The vetusia_server/1 predicate is the configurable entry point.  Users
 * can start the server on any port by calling vetusia_server(Port) directly
 * without modifying the generated file.  The generated main/0 calls it with
 * the default port supplied to generate_web_server/3 (default: 8080).
 *
 * No JavaScript is used for control flow or input handling.
 *
 * Usage
 * -----
 *   ?- use_module('src/web_server_generator').
 *   ?- generate_web_server('examples/input_example.pl', 'output/web_example.pl').
 *   ?- generate_web_server('examples/input_example.pl', 'output/web_example.pl', 9090).
 *
 * @author  Lucian Green
 * @license BSD-3-Clause
 */

:- use_module(library(lists)).
:- use_module(library(apply)).

:- use_module(reader).
:- use_module(checkpoint_detector).
:- use_module(continuation_extractor).
:- use_module(html_output).

% ==========================================================================
% Public API
% ==========================================================================

%% generate_web_server(+InputFile:atom, +OutputFile:atom) is det.
%
%  Convert a terminal Prolog source file to a web Prolog server file.
%  The generated server listens on the default port 8080.
%
%  Example:
%    ?- generate_web_server('examples/input_example.pl', 'output/web_example.pl').
generate_web_server(InputFile, OutputFile) :-
    generate_web_server(InputFile, OutputFile, 8080).

%% generate_web_server(+InputFile:atom, +OutputFile:atom, +Port:integer) is det.
%
%  Like generate_web_server/2 but the generated main/0 predicate starts the
%  server on Port.  Users can also call vetusia_server(Port) directly on
%  any port after loading the generated file.
%
%  Example:
%    ?- generate_web_server('examples/input_example.pl', 'output/web_example.pl', 9090).
generate_web_server(InputFile, OutputFile, Port) :-
    read_and_normalise(InputFile, NormClauses),
    wsg_find_main(NormClauses, MainBody, VN, AuxNorms),
    detect_checkpoints(MainBody, VN, main/0, CPs),
    extract_continuations(CPs, VN, main/0, Steps),
    open(OutputFile, write, Out),
    wsg_write_program(Out, Steps, VN, AuxNorms, Port),
    close(Out).

% ==========================================================================
% Internal: locate main/0 in the normalised clause list
% ==========================================================================

%% wsg_find_main(+NormClauses, -Body, -VN, -Others) is det.
%
%  Find the norm_clause(main, Body, VN) entry in NormClauses.
%  Others is the list of all remaining clauses (used for auxiliary emission).
wsg_find_main([norm_clause(main, Body, VN) | Rest], Body, VN, Rest) :- !.
wsg_find_main([C | Rest], Body, VN, [C | Others]) :-
    wsg_find_main(Rest, Body, VN, Others).

% ==========================================================================
% Internal: top-level emission
% ==========================================================================

%% wsg_write_program(+Out, +Steps, +VN, +AuxNorms, +Port) is det.
%
%  Write the complete generated web server program to Out.
wsg_write_program(Out, Steps, VN, AuxNorms, Port) :-
    wsg_emit_header(Out),
    nl(Out),
    format(Out, "%% === HTTP Library Imports ===~n", []),
    wsg_emit_use_modules(Out),
    nl(Out),
    format(Out, "%% === HTTP Handler Declarations ===~n", []),
    wsg_emit_handler_decls(Out, Steps),
    nl(Out),
    format(Out, "%% === Server Bootstrap ===~n", []),
    wsg_emit_server_bootstrap(Out, Port),
    format(Out, "%% === HTML Output Helpers ===~n", []),
    emit_html_helpers(Out),
    nl(Out),
    format(Out, "%% === HTTP Handler Clauses ===~n", []),
    maplist(write_cont_step(Out, VN), Steps),
    ( AuxNorms = [] -> true
    ;   nl(Out),
        format(Out, "%% === Auxiliary Predicates ===~n", []),
        wsg_emit_aux_clauses(Out, AuxNorms)
    ).

% ==========================================================================
% Internal: boilerplate emission
% ==========================================================================

%% wsg_emit_header(+Out) is det.
%  Write the generator identification comment at the top of the file.
wsg_emit_header(Out) :-
    format(Out, "%% Generated by vetusiapl2webpl — web_server_generator~n", []),
    format(Out, "%% --------------------------------------------------~n~n", []).

%% wsg_emit_use_modules(+Out) is det.
%  Write use_module directives for all required SWI-Prolog HTTP libraries.
wsg_emit_use_modules(Out) :-
    format(Out, ":- use_module(library(http/thread_httpd)).~n",  []),
    format(Out, ":- use_module(library(http/http_dispatch)).~n", []),
    format(Out, ":- use_module(library(http/html_write)).~n",    []),
    format(Out, ":- use_module(library(http/http_parameters)).~n",[]),
    format(Out, ":- use_module(library(http/http_header)).~n",   []).

%% wsg_emit_handler_decls(+Out, +Steps) is det.
%
%  Write http_handler/3 declarations.
%  The first step is always declared as the GET root handler (landing page).
%  All subsequent steps are declared as POST handlers.
wsg_emit_handler_decls(Out, Steps) :-
    ( Steps = [cont_step(LandingPadName, _, _, _) | PostSteps] -> true
    ;   LandingPadName = step_0, PostSteps = []
    ),
    format(Out, ":- http_handler(root(.), ~w, []).~n", [LandingPadName]),
    maplist(wsg_emit_post_handler_decl(Out), PostSteps).

wsg_emit_post_handler_decl(Out, cont_step(Name, _, _, _)) :-
    format(Out, ":- http_handler(root(~w), ~w, [method(post)]).~n", [Name, Name]).

%% wsg_emit_server_bootstrap(+Out, +Port) is det.
%
%  Write the server entry predicate and main/0 initialisation.
%
%  vetusia_server/1 is the configurable public entry point:
%    vetusia_server(Port) :- http_server(http_dispatch, [port(Port)]).
%
%  main/0 is the :- initialization target and calls vetusia_server
%  with the port supplied to generate_web_server/3.
wsg_emit_server_bootstrap(Out, Port) :-
    format(Out, "vetusia_server(Port) :-~n", []),
    format(Out, "    http_server(http_dispatch, [port(Port)]).~n~n", []),
    format(Out, ":- initialization(main, main).~n~n", []),
    format(Out, "main :-~n    vetusia_server(~w).~n", [Port]).

% ==========================================================================
% Internal: auxiliary clause emission
% ==========================================================================

%% wsg_emit_aux_clauses(+Out, +NormClauses) is det.
%
%  Write auxiliary clauses from the input program.
%  Directives and the main/0 clause are intentionally skipped:
%  the generator produces its own initialization directive and main/0.
wsg_emit_aux_clauses(_, []).
wsg_emit_aux_clauses(Out, [NC | Rest]) :-
    wsg_emit_aux_norm_clause(Out, NC),
    wsg_emit_aux_clauses(Out, Rest).

%% wsg_emit_aux_norm_clause(+Out, +NormClause) is det.
%
%  Emit a single auxiliary clause, reconstructing the Prolog source form
%  from the normalised representation via wsg_denormalise_body/2.
%  Directives (directive/1) and the main/0 clause are skipped silently.
wsg_emit_aux_norm_clause(Out, norm_clause(Head, NormBody, VN)) :-
    Head \= main, !,
    wsg_denormalise_body(NormBody, Body),
    ( Body = true ->
        Clause = Head
    ;   Clause = (Head :- Body)
    ),
    nl(Out),
    write_term(Out, Clause, [variable_names(VN), quoted(true)]),
    format(Out, ".~n", []).
wsg_emit_aux_norm_clause(_, _).       % skip directive/1 and main/0

% ==========================================================================
% Internal: denormalisation (norm_* → raw Prolog terms)
% ==========================================================================

%% wsg_denormalise_body(+NormBody, -Body) is det.
%
%  Convert a normalised body term back into standard Prolog syntax.
%  This is used to reconstruct auxiliary clauses for emission via
%  write_term/3.
wsg_denormalise_body(norm_true, true) :- !.
wsg_denormalise_body(norm_cut, !) :- !.
wsg_denormalise_body(norm_conj(A, B), (DA, DB)) :- !,
    wsg_denormalise_body(A, DA),
    wsg_denormalise_body(B, DB).
wsg_denormalise_body(norm_disj(A, B), (DA ; DB)) :- !,
    wsg_denormalise_body(A, DA),
    wsg_denormalise_body(B, DB).
wsg_denormalise_body(norm_if_then(C, T), (DC -> DT)) :- !,
    wsg_denormalise_body(C, DC),
    wsg_denormalise_body(T, DT).
wsg_denormalise_body(norm_if_then_else(C, T, E), (DC -> DT ; DE)) :- !,
    wsg_denormalise_body(C, DC),
    wsg_denormalise_body(T, DT),
    wsg_denormalise_body(E, DE).
wsg_denormalise_body(norm_read_string(S, Sents, Pad, Len, Var),
                     read_string(S, Sents, Pad, Len, Var)) :- !.
wsg_denormalise_body(norm_read_password(Prompt, Var), read_password(Prompt, Var)) :- !.
wsg_denormalise_body(norm_read_password(Var), read_password(Var)) :- !.
wsg_denormalise_body(norm_output(G), G) :- !.
wsg_denormalise_body(norm_goal(G), G) :- !.
wsg_denormalise_body(G, G).           % fallback: pass through unchanged
